WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM ( VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815), (247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517), (265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142), (636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528), (77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705), (1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489), (747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983), (81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475), (74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351), (70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534), (77093),(154),(1001),(70030),(576),(70429),(217),(960),(196420),(94782),(300439) ) AS x(dest_id) ), -- 1. Identify the Cohort (Successful Pilgrim Bookings) base_users AS ( SELECT * FROM ( SELECT __time AS basedate, rb_user_id, src_id AS base_src_id, dest_id AS base_dest_id, ROW_NUMBER() OVER (PARTITION BY rb_user_id ORDER BY __time ASC) as rn FROM user_interaction.confirm_order_details WHERE __time >= TIMESTAMP '2026-01-01 00:00:00' AND __time < TIMESTAMP '2026-03-01 00:00:00' AND status_str = 'SUCCESS' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND tin IS NOT NULL AND dest_id IN (SELECT dest_id FROM piligrim_dest_list) ) WHERE rn = 1 -- Only the first pilgrim booking ), -- 2. Relevant Searches within 14 days of booking searches_in_window AS ( SELECT b.rb_user_id, b.base_src_id, b.base_dest_id, b.basedate, s.src_id AS search_src_id, s.dest_id AS search_dest_id, s.searchdate FROM base_users b JOIN ( -- Pre-filtering search details by user cohort improves speed significantly SELECT DISTINCT rb_user_id, src_id, dest_id, __time AS searchdate FROM user_interaction.search_details WHERE __time >= TIMESTAMP '2026-01-01 00:00:00' AND __time < TIMESTAMP '2026-03-16 00:00:00' AND os = 'Android' AND country = 'IND' ) s ON s.rb_user_id = b.rb_user_id WHERE s.searchdate > b.basedate AND s.searchdate <= date_add('day', 14, b.basedate) -- THE 14 DAY ROLLING WINDOW ), -- 3. Relevant Confirmations within 14 days of booking confirmations_in_window AS ( SELECT s.rb_user_id, s.search_src_id, s.search_dest_id, s.basedate, MIN(rc.confirmdate) as first_confirm_after_search FROM searches_in_window s JOIN ( SELECT DISTINCT rb_user_id, src_id, dest_id, __time AS confirmdate FROM user_interaction.confirm_order_details WHERE __time >= TIMESTAMP '2026-01-01 00:00:00' AND __time < TIMESTAMP '2026-03-16 00:00:00' AND status_str = 'SUCCESS' AND channel = 'MOBILE_APP' ) rc ON rc.rb_user_id = s.rb_user_id AND rc.src_id = s.search_src_id AND rc.dest_id = s.search_dest_id WHERE rc.confirmdate > s.searchdate AND rc.confirmdate <= date_add('day', 15, s.basedate) -- Ensure confirmation is also in window GROUP BY 1, 2, 3, 4 ) SELECT 'Overall' AS Returntype, COUNT(DISTINCT b.rb_user_id) AS total_base_users, -- Search Metrics COUNT(DISTINCT sw.rb_user_id) AS any_sd_searched_users, COUNT(DISTINCT CASE WHEN sw.search_src_id = sw.base_dest_id AND sw.search_dest_id = sw.base_src_id THEN sw.rb_user_id END) AS return_route_searched_users, COUNT(DISTINCT CASE WHEN sw.search_src_id = sw.base_dest_id AND pd1.dest_id IS NOT NULL AND sw.search_dest_id <> sw.base_src_id THEN sw.rb_user_id END) AS diff_pilgrim_searched_users, COUNT(DISTINCT CASE WHEN sw.search_src_id = sw.base_dest_id AND pd1.dest_id IS NULL THEN sw.rb_user_id END) AS non_pilgrim_searched_users, COUNT(DISTINCT CASE WHEN pd1.dest_id IS NULL AND pd2.dest_id IS NULL THEN sw.rb_user_id END) AS other_sd_searched_users, -- Confirmation Metrics COUNT(DISTINCT cw.rb_user_id) AS any_sd_confirmed_users, COUNT(DISTINCT CASE WHEN cw.search_src_id = b.base_dest_id AND cw.search_dest_id = b.base_src_id THEN cw.rb_user_id END) AS return_route_confirmed_users, COUNT(DISTINCT CASE WHEN cw.search_src_id = b.base_dest_id AND pd_c.dest_id IS NOT NULL AND cw.search_dest_id <> b.base_src_id THEN cw.rb_user_id END) AS diff_pilgrim_confirmed_users, COUNT(DISTINCT CASE WHEN cw.search_src_id = b.base_dest_id AND pd_c.dest_id IS NULL THEN cw.rb_user_id END) AS non_pilgrim_confirmed_users, COUNT(DISTINCT CASE WHEN pd_c_dest.dest_id IS NULL AND pd_c_src.dest_id IS NULL AND cw.rb_user_id IS NOT NULL THEN cw.rb_user_id END) AS other_sd_confirmed_users FROM base_users b LEFT JOIN searches_in_window sw ON b.rb_user_id = sw.rb_user_id AND b.basedate = sw.basedate LEFT JOIN confirmations_in_window cw ON b.rb_user_id = cw.rb_user_id AND b.basedate = cw.basedate LEFT JOIN piligrim_dest_list pd1 ON sw.search_dest_id = pd1.dest_id LEFT JOIN piligrim_dest_list pd2 ON sw.search_src_id = pd2.dest_id LEFT JOIN piligrim_dest_list pd_c ON cw.search_dest_id = pd_c.dest_id LEFT JOIN piligrim_dest_list pd_c_dest ON cw.search_dest_id = pd_c_dest.dest_id LEFT JOIN piligrim_dest_list pd_c_src ON cw.search_src_id = pd_c_src.dest_id GROUP BY 1;
